script.setup:
// Shapely merged random circles into islands and offset them in and out (recipe
// shapely.offset-rings → rings.json); the scene draws the rings like a contour map.
const data = await (await fetch(ctx.assets["rings.json"])).json();
const gl = ctx.gl;
const makeLines = (data, stride) => {
  const vao = gl.createVertexArray(), buffer = gl.createBuffer();
  gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, stride * 4, 0);
  gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, stride - 2, gl.FLOAT, false, stride * 4, 8);
  gl.bindVertexArray(null);
  return { vao, count: data.length / stride };
};
const segs = [];
for (const ring of data.rings) {
  const p = ring.points;
  for (let k = 0; k + 3 < p.length; k += 2) segs.push(p[k], p[k + 1], ring.level, p[k + 2], p[k + 3], ring.level);
}
// Center the islands and fill the area, whatever the seed made.
let x0 = 1, x1 = 0, y0 = 1, y1 = 0;
for (let i = 0; i < segs.length; i += 3) { x0 = Math.min(x0, segs[i]); x1 = Math.max(x1, segs[i]); y0 = Math.min(y0, segs[i + 1]); y1 = Math.max(y1, segs[i + 1]); }
const k = 0.94 / Math.max(x1 - x0, y1 - y0);
for (let i = 0; i < segs.length; i += 3) { segs[i] = 0.5 + (segs[i] - (x0 + x1) / 2) * k; segs[i + 1] = 0.5 + (segs[i + 1] - (y0 + y1) / 2) * k; }
Object.assign(ctx.state, { data, lines: makeLines(new Float32Array(segs), 3), p: ctx.utils.createProgram("#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in float a_level;\nuniform vec2 u_fit; uniform vec2 u_offset; out float v_level;\nvoid main(){ v_level = a_level; gl_Position = vec4((a_position * 2.0 - 1.0) * u_fit + u_offset, 0.0, 1.0); }", "#version 300 es\nprecision highp float; in float v_level; out vec4 outColor; uniform float u_time; uniform float u_wave;\nuniform vec3 u_inside; uniform vec3 u_outside;\nvoid main(){ float glow = 0.35 + 0.65 * pow(0.5 + 0.5 * sin(v_level * 0.55 - u_time * u_wave), 4.0);\n  vec3 c = v_level < 0.5 ? u_inside : u_outside; outColor = vec4(c * glow * 1.4, 1.0); }") });
ctx.publish("rings", data.rings.length);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const area = s.data.aspect, view = w / h;
const fit = area > view ? [0.95, 0.95 * view / area] : [0.95 * area / view, 0.95];
gl.clearColor(0.02, 0.025, 0.035, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.useProgram(s.p);
ctx.utils.setStandardUniforms(s.p);
ctx.utils.setUniforms(s.p, { u_fit: fit });
gl.bindVertexArray(s.lines.vao);
// WebGL draws 1 px lines only; four shifted passes make them 2 px.
for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]]) {
  ctx.utils.setUniforms(s.p, { u_offset: [dx * 2 / w, dy * 2 / h] });
  gl.drawArrays(gl.LINES, 0, s.lines.count);
}
gl.bindVertexArray(null);
